(function(){'use strict';const previous=renderInspector;renderInspector=function(){previous();const o=current();if(!o)return;const host=$('#inspectorContent');if(o.type==='character'){host.insertAdjacentHTML('beforeend',`<section data-look-panel><h3>Eye direction</h3><label class="field">Eyelids<select id="eyeState">${["auto","open","closed"].map(k=>`<option value="${k}" ${(o.eyeState||"auto")===k?"selected":""}>${k}</option>`).join("")}</select></label><div class="gaze-grid">${[['up-left','↖'],['up','↑'],['up-right','↗'],['left','←'],['direct','●'],['right','→'],['down-left','↙'],['down','↓'],['down-right','↘']].map(([k,icon])=>`<button data-gaze="${k}" class="${(o.gaze||'direct')===k?'active':''}" aria-label="Look ${k}" title="Look ${k.replaceAll('-',' ')}">${icon}</button>`).join('')}</div><p class="note">Eye direction is saved on this frame. Open / Closed overrides movement and emotion. Back views hide the face. Imported heads need face expressions enabled.</p></section>`);$('#eyeState').onchange=()=>{remember();selectedObjects().filter(v=>v.type==='character').forEach(v=>v.eyeState=$('#eyeState').value);changed()};const look=host.querySelector('[data-look-panel]'),performance=[...host.children].find(s=>s.querySelector('h3')?.textContent==='Character performance');if(performance&&look)host.insertBefore(look,host.children[[...host.children].indexOf(performance)+1]||null);$$('[data-gaze]').forEach(b=>b.onclick=()=>{remember();selectedObjects().filter(o=>o.type==='character').forEach(o=>o.gaze=b.dataset.gaze);changed()})}if(['clock','alarm','shop','night-digital-clock','night-cafe'].includes(o.type)){const analog=['clock','alarm'].includes(o.type),digital=o.type==='night-digital-clock',key=analog?'clockTime':o.type==='shop'?'label':'text',fallback=analog?'04:00':digital?'23:58':o.type==='shop'?'LITTLE SHOP':'CAFE';host.insertAdjacentHTML('beforeend',`<section><h3>Object settings</h3><label class="field">${analog||digital?'Time':'Sign text'}<input id="smartValue" type="${analog||digital?'time':'text'}" value="${esc(o[key]&&o[key]!=='A little story'?o[key]:fallback)}" maxlength="40"></label><p class="note">${analog?'The hour and minute hands follow this time.':'Saved per frame and included in exports.'}</p></section>`);$('#smartValue').onchange=()=>{const v=$('#smartValue').value;if((analog||digital)&&!/^\d{2}:\d{2}$/.test(v))return;remember();o[key]=v;changed()}}const section=[...host.children].find(s=>s.querySelector('h3')?.textContent==='Visual effects');if(section){section.insertAdjacentHTML('beforeend',`<label class="field">Attach effects<select id="effectAnchor">${['auto','head','body'].map(k=>`<option value="${k}" ${(o.effectAnchor||'auto')===k?'selected':''}>${k==='auto'?'Auto (near head / object)':k==='head'?'Head (characters)':'Body / object center'}</option>`).join('')}</select></label><label class="field">Horizontal offset<input id="effectOffsetX" type="number" value="${o.effectOffsetX||0}"></label><label class="field">Vertical offset<input id="effectOffsetY" type="number" value="${o.effectOffsetY||0}"></label>`);for(const key of ['effectAnchor','effectOffsetX','effectOffsetY'])$('#'+key).onchange=()=>{const v=key==='effectAnchor'?$('#'+key).value:Number($('#'+key).value);if(typeof v==='number'&&!Number.isFinite(v))return;remember();selectedObjects().forEach(o=>o[key]=v);changed()}}window.WorkspaceUI?.filter()};renderInspector()})();
